--
-- Структура таблицы `recipes`
--

CREATE TABLE `recipes` (
  `id_recipes` int(10) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `country` varchar(100) DEFAULT NULL,
  `cooking_time_minutes` int(11) DEFAULT NULL,
  `calories` int(11) DEFAULT NULL,
  `instructions` text NOT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `chef_id` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Дамп данных таблицы `recipes`
--

INSERT INTO `recipes` (`id_recipes`, `title`, `country`, `cooking_time_minutes`, `calories`, `instructions`, `image_url`, `chef_id`, `created_at`) VALUES
(1, 'Блины классические', 'Россия', 40, 230, '1. Просейте муку в глубокую миску. Добавьте яйца, сахар и соль, перемешайте.\n2. Влейте молоко небольшими порциями, тщательно перемешивая, чтобы не было комков.\n3. Добавьте растительное масло, перемешайте.\n4. Разогрейте сковороду, смажьте маслом.\n5. Выливайте тесто тонким слоем, жарьте 1-2 минуты с каждой стороны до золотистого цвета.\n6. Подавайте горячими со сметаной, вареньем или медом.', 'klassicheskie-bliny.jpg', 1, '2026-06-17 15:05:57'),
(2, 'Стейк Рибай', 'США', 25, 350, '1. Достаньте стейк из холодильника за 30 минут до приготовления.\n2. Посолите и поперчите с обеих сторон.\n3. Разогрейте сковороду-гриль на сильном огне.\n4. Обжаривайте стейк 3-4 минуты с каждой стороны для medium rare.\n5. Дайте отдохнуть 5 минут под фольгой перед подачей.', 'steik-ribai.jpg', 1, '2026-06-17 15:05:57'),
(3, 'Паста Карбонара', 'Италия', 20, 450, '1. Отварите спагетти в подсоленной воде до состояния al dente.\n2. Обжарьте панчетту или бекон до хрустящей корочки.\n3. Смешайте яйца с тертым пармезаном и черным перцем.\n4. Слейте воду с пасты, оставив 1 стакан воды.\n5. Быстро смешайте горячую пасту с яичной смесью и беконом.\n6. Добавьте немного воды от пасты для кремовой консистенции.', 'pasta-karbonara-s-bekonom-i-slivkami.jpg', 1, '2026-06-19 19:16:45'),
(4, 'Греческий салат', 'Греция', 15, 180, '1. Нарежьте помидоры крупными кусками.\n2. Огурцы нарежьте полукружиями.\n3. Красный лук нарежьте тонкими кольцами.\n4. Фету нарежьте кубиками или ломтиками.\n5. Смешайте овощи в салатнице, добавьте оливки.\n6. Сверху выложите фету, посыпьте орегано.\n7. Полейте оливковым маслом и подавайте.', 'grecheskii-salat-s-pekinskoi-kapustoi.jpg', NULL, '2026-06-19 19:16:45'),
(5, 'Том Ям', 'Таиланд', 30, 120, '1. Вскипятите куриный бульон с лемонграссом, галангалом и листьями лайма.\n2. Добавьте грибы шиитаке или вешенки, варите 5 минут.\n3. Добавьте креветки, варите 2-3 минуты до готовности.\n4. Снимите с огня, добавьте рыбный соус, сок лайма и чили.\n5. Посыпьте кинзой и подавайте горячим.', 'taiskii-sup-tom-yam-kung-s-krevetkami.jpg', 3, '2026-06-19 19:16:45'),
(6, 'Борщ украинский', 'Украина', 90, 95, '1. Сварите говяжий бульон (1.5 часа).\n2. Натрите свеклу, морковь, лук.\n3. Обжарьте овощи, добавьте томатную пасту.\n4. Нарежьте картофель кубиками, капусту нашинкуйте.\n5. Добавьте картофель в бульон, варите 15 минут.\n6. Добавьте капусту, варите 10 минут.\n7. Добавьте зажарку, варите 5 минут.\n8. Подавайте со сметаной и зеленью.', 'borshch-klassicheskii-s-govyadinoi.jpg', 1, '2026-06-19 19:16:45'),
(7, 'Тирамису', 'Италия', 30, 420, '1. Взбейте желтки с сахаром до белизны.\n2. Добавьте маскарпоне, взбейте до однородности.\n3. Отдельно взбейте белки до пиков, аккуратно вмешайте в крем.\n4. Смешайте кофе с ликером.\n5. Окунайте савоярди в кофе, выложите в форму.\n6. Сверху выложите крем, повторите слои.\n7. Уберите в холодильник на 4 часа.\n8. Перед подачей посыпьте какао.', 'domashnii-klassicheskii-tiramisu.jpg', NULL, '2026-06-19 19:16:45'),
(9, 'Оливье', 'Россия', 40, 180, '1. Отварите картофель и морковь до готовности, остудите.\n2. Отварите яйца вкрутую.\n3. Нарежьте все ингредиенты мелкими кубиками.\n4. Добавьте зеленый горошек.\n5. Заправьте майонезом, посолите, поперчите.\n6. Перемешайте и подавайте.', 'klassicheskii-olive-s-myasom.jpg', 1, '2026-06-19 19:16:45'),
(11, 'Гуакамоле', 'Мексика', 10, 160, '1. Разрежьте авокадо пополам, удалите косточку.\n2. Выньте мякоть ложкой в миску.\n3. Разомните вилкой, оставив небольшие кусочки.\n4. Добавьте мелко нарезанный лук, помидоры, кинзу.\n5. Добавьте сок лайма, соль, перец чили.\n6. Перемешайте и подавайте с начос.', 'sous-guakamole-klassicheskii.jpg', 3, '2026-06-19 19:16:45'),
(12, 'Чизкейк', 'США', 80, 380, '1. Измельчите печенье, смешайте с растопленным маслом.\n2. Выложите в форму, утрамбуйте, уберите в холодильник.\n3. Взбейте сливочный сыр с сахаром.\n4. Добавьте яйца по одному, взбивая.\n5. Добавьте сметану, ваниль, лимонный сок.\n6. Вылейте на основу.\n7. Выпекайте при 160°C 50-60 минут.\n8. Остудите, уберите в холодильник на 4 часа.', 'chizkeik-nu-iork-klassicheskii.jpg', 1, '2026-06-19 19:16:45'),
(13, 'Паста Болоньезе', 'Италия', 60, 420, '1. Обжарьте лук, морковь, сельдерей.\r\n2. Добавьте фарш, обжарьте до коричневого цвета.\r\n3. Добавьте томаты, томатную пасту, вино.\r\n4. Тушите на медленном огне 40 минут.\r\n5. Отварите пасту (тальятелле или спагетти).\r\n6. Смешайте пасту с соусом.\r\n7. Подавайте с пармезаном.', 'spagetti-boloneze-s-farshem-i-tomatnoi-pastoi.jpg', 5, '2026-06-21 07:00:00'),
(14, 'Лазанья', 'Италия', 75, 380, '1. Приготовьте соус болоньезе (фарш, томаты, овощи).\n2. Приготовьте соус бешамель (масло, мука, молоко).\n3. Отварите листы лазаньи.\n4. Выложите слоями: листы, болоньезе, бешамель, сыр.\n5. Повторите 3-4 слоя.\n6. Сверху посыпьте пармезаном.\n7. Выпекайте при 180°C 35-40 минут.', 'lenivaya-lazanya-iz-lavasha-s-farshem-v-duxovke.jpg', 5, '2026-06-21 07:00:00'),
(16, 'Цезарь с курицей', 'США', 25, 280, '1. Обжарьте куриное филе, нарежьте ломтиками.\n2. Приготовьте сухарики из багета.\n3. Приготовьте соус: анчоусы, чеснок, желток, лимон, оливковое масло, пармезан.\n4. Порвите салат романо.\n5. Смешайте салат с соусом.\n6. Сверху выложите курицу, сухарики, пармезан.', 'cezar-s-pekinskoi-kapustoi.jpg', 6, '2026-06-21 07:00:00'),
(17, 'Паста с морепродуктами', 'Италия', 25, 380, '1. Отварите пасту (лингвини или спагетти).\n2. Обжарьте чеснок в оливковом масле.\n3. Добавьте креветки, мидии, кальмары.\n4. Готовьте 5-7 минут.\n5. Добавьте белое вино, выпарите.\n6. Добавьте томаты черри, петрушку.\n7. Смешайте с пастой, подавайте.', 'pasta-lingvini-s-krevetkami.jpg', 6, '2026-06-21 07:00:00'),
(18, 'Яичница с беконом', 'Великобритания', 10, 320, '1. Нарежьте бекон ломтиками.\n2. Обжарьте бекон на сковороде до хрустящей корочки.\n3. Разбейте яйца на сковороду.\n4. Жарьте 2-3 минуты до желаемой консистенции.\n5. Посолите, поперчите.\n6. Подавайте с тостами.', 'amerikanskaya-yaichnica-s-bekonom.jpg', 6, '2026-06-21 07:00:00'),
(21, 'Глинтвейн', 'Германия', 20, 0, '1. Налейте красное вино в кастрюлю.\n2. Добавьте палочки корицы, гвоздику, бадьян.\n3. Добавьте дольки апельсина, яблока.\n4. Добавьте мед или сахар.\n5. Нагрейте до 70°C (не кипятите!).\n6. Настаивайте 10 минут.\n7. Подавайте горячим.', 'glintvein-klassicheskii.jpg', 7, '2026-06-21 07:00:00'),
(22, 'Утка по-пекински', 'Китай', 180, 450, '1. Натрите утку солью и специями.\n2. Обдайте кипятком, высушите.\n3. Оставьте в холодильнике на ночь.\n4. Запекайте при 180°C 2 часа.\n5. Нарежьте тонкими ломтиками.\n6. Подавайте с блинчиками, соусом хойсин, огурцом и зеленым луком.', 'utka-po-pekinski.jpg', 8, '2026-06-21 07:00:00'),
(23, 'Жаркое по-домашнему', 'Россия', 90, 280, '1. Нарежьте мясо (говядину или свинину) кубиками.\n2. Обжарьте до корочки.\n3. Добавьте лук, морковь, обжарьте.\n4. Добавьте картофель кубиками.\n5. Залейте бульоном или водой.\n6. Тушите под крышкой 1 час.\n7. Добавьте лавровый лист, перец.\n8. Подавайте со сметаной.', 'jarkoe-iz-govyadiny-na-skovorode.jpg', 8, '2026-06-21 07:00:00'),
(24, 'Медовик', 'Россия', 120, 380, '1. Растопите мед с маслом.\n2. Добавьте яйца, сахар, соду.\n3. Добавьте муку, замесите тесто.\n4. Раскатайте 8-10 коржей.\n5. Выпекайте каждый корж 5-7 минут при 180°C.\n6. Приготовьте крем (сметана с сахаром).\n7. Промажьте коржи кремом.\n8. Оставьте пропитываться на ночь.', 'medovyi-tort-s-medovym-kremom.jpg', 8, '2026-06-21 07:00:00'),
(25, 'Суши Филадельфия', 'Япония', 40, 280, '1. Сварите рис для суши с уксусом.\n2. Нарежьте лосось тонкими ломтиками.\n3. Нарежьте авокадо и огурец соломкой.\n4. Разложите нори на коврике.\n5. Выложите рис, переверните.\n6. Выложите сыр, авокадо, огурец.\n7. Сверните ролл.\n8. Сверху выложите лосось.\n9. Нарежьте на 8 частей.', 'salat-filadelfiya-klassicheskii.jpg', 9, '2026-06-21 07:00:00'),
(26, 'Рамен', 'Япония', 120, 420, '1. Сварите бульон (свиные кости, 4-6 часов).\n2. Добавьте соевый соус, мирин, саке.\n3. Отварите яйца всмятку (6 минут).\n4. Отварите лапшу рамен.\n5. Нарежьте свинину чашу.\n6. Соберите рамен: лапша, бульон, свинина, яйцо, нори, зеленый лук.', 'sup-ramen-s-krevetkami.jpg', 9, '2026-06-21 07:00:00'),
(27, 'Темпура', 'Япония', 25, 280, '1. Приготовьте кляр: ледяная вода, мука, яйцо.\n2. Нарежьте овощи (баклажаны, батат, кабачки).\n3. Обмакните в кляр.\n4. Обжарьте во фритюре при 170°C 2-3 минуты.\n5. Подавайте с соусом тентсую.', 'roll-tempura-v-domashnix-usloviyax-sushi.jpg', 9, '2026-06-21 07:00:00'),
(28, 'Бургер с говядиной', 'США', 25, 620, '1. Приготовьте котлету. 2. Соберите бургер. 3. Подавайте с картофелем фри.', 'kotlety-dlya-burgerov-iz-farsha.jpg', 10, '2026-06-21 07:00:00'),
(29, 'Омлет с креветками', '', 45, 550, '1. ', 'omlet-s-krevetkami.png', 5, '2026-06-21 07:00:00'),
(30, 'Наполеон', 'Франция', 90, 480, '1. Раскатайте тесто. 2. Выпекайте коржи. 3. Промажьте кремом.', 'napoleon-tort-iz-gotovogo-sloenogo-testa.jpg', 10, '2026-06-21 07:00:00'),
(31, 'Сырники', 'Россия', 25, 320, '1. Смешайте творог с яйцом. 2. Добавьте муку. 3. Обжарьте.', 'syrniki-iz-tvoroga-s-mukoi-na-skovorode.jpg', 8, '2026-06-21 07:00:00'),
(32, 'Смузи ягодный', 'США', 10, 50, 'Для приготовления клубнично-бананового смузи вам понадобится всего три базовых компонента: клубника, банан и молоко.\r\n\r\nПо желанию, для большей сладости, в напиток можно добавить немного меда или сахара (если банан не слишком спелый). А также 2-3 столовые ложки овсяных хлопьев быстрого приготовления, для придания напитку большей питательности.\r\n\r\nИнгредиенты для клубнично-бананового смузи\r\n\r\nВымойте ягоды клубники и удалите плодоножки.\r\n\r\nПомыть клубнику\r\n\r\nОчистите и нарежьте бананы небольшими ломтиками.\r\n\r\nПорезать клубнику и банан\r\n\r\nПоместите фрукты в чашу блендера. По желанию, добавьте 1-2 ст.л. сахара (количество сахара регулируйте, в зависимости от сладости фруктов и собственных вкусовых предпочтений).\r\n\r\nПоложить в блендер клубнику и банан\r\n\r\nВзбейте компоненты несколько минут, до получения однородного фруктового пюре. Добавьте молоко и взбейте все еще 1-2 минуты на высокой скорости.\r\n\r\nПюрировать клубнику с бананом\r\n\r\nРазлейте напиток по бокалам, украсьте по настроению и подавайте к столу.\r\n\r\nВлить молоко\r\n\r\nКлубнично-банановый смузи готов. Приятного аппетита.', 'smuzi.jpg', 7, '2026-06-21 07:00:00');

