--
-- Структура для представления `view_low_calorie_recipes`
--
DROP TABLE IF EXISTS `view_low_calorie_recipes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_low_calorie_recipes`  AS SELECT `recipes`.`id_recipes` AS `id_recipes`, `recipes`.`title` AS `title`, `recipes`.`country` AS `country`, `recipes`.`cooking_time_minutes` AS `cooking_time_minutes`, `recipes`.`calories` AS `calories`, `recipes`.`image_url` AS `image_url`, `recipes`.`instructions` AS `instructions` FROM `recipes` WHERE `recipes`.`calories` <= 300 ORDER BY `recipes`.`calories` ASC ;

-- --------------------------------------------------------

--
-- Структура для представления `view_recipes_by_category`
--
DROP TABLE IF EXISTS `view_recipes_by_category`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_recipes_by_category`  AS SELECT `r`.`id_recipes` AS `id_recipes`, `r`.`title` AS `title`, `r`.`country` AS `country`, `r`.`cooking_time_minutes` AS `cooking_time_minutes`, `r`.`calories` AS `calories`, `r`.`image_url` AS `image_url`, `c`.`name` AS `category_name` FROM ((`recipes` `r` join `recipe_categories` `rc` on(`r`.`id_recipes` = `rc`.`recipe_id`)) join `categories` `c` on(`rc`.`category_id` = `c`.`id_categories`)) ORDER BY `c`.`name` ASC, `r`.`title` ASC ;

-- --------------------------------------------------------

--
-- Структура для представления `view_recipes_by_cooking_time`
--
DROP TABLE IF EXISTS `view_recipes_by_cooking_time`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_recipes_by_cooking_time`  AS SELECT `recipes`.`id_recipes` AS `id_recipes`, `recipes`.`title` AS `title`, `recipes`.`country` AS `country`, `recipes`.`cooking_time_minutes` AS `cooking_time_minutes`, `recipes`.`calories` AS `calories`, `recipes`.`image_url` AS `image_url`, CASE WHEN `recipes`.`cooking_time_minutes` <= 15 THEN 'Быстро (до 15 мин)' WHEN `recipes`.`cooking_time_minutes` <= 30 THEN 'Средне (15-30 мин)' WHEN `recipes`.`cooking_time_minutes` <= 60 THEN 'Долго (30-60 мин)' ELSE 'Очень долго (более 60 мин)' END AS `time_category` FROM `recipes` ORDER BY `recipes`.`cooking_time_minutes` ASC ;

-- --------------------------------------------------------

--
-- Структура для представления `view_recipes_by_diet`
--
DROP TABLE IF EXISTS `view_recipes_by_diet`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_recipes_by_diet`  AS SELECT `r`.`id_recipes` AS `id_recipes`, `r`.`title` AS `title`, `r`.`country` AS `country`, `r`.`cooking_time_minutes` AS `cooking_time_minutes`, `r`.`calories` AS `calories`, `r`.`image_url` AS `image_url`, `d`.`name` AS `diet_name` FROM ((`recipes` `r` join `recipe_diets` `rd` on(`r`.`id_recipes` = `rd`.`recipe_id`)) join `diets` `d` on(`rd`.`diet_id` = `d`.`id_diets`)) ORDER BY `d`.`name` ASC, `r`.`title` ASC ;

-- --------------------------------------------------------

--
-- Структура для представления `view_recipes_by_ingredients`
--
DROP TABLE IF EXISTS `view_recipes_by_ingredients`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_recipes_by_ingredients`  AS SELECT `r`.`id_recipes` AS `id_recipes`, `r`.`title` AS `title`, `r`.`country` AS `country`, `r`.`cooking_time_minutes` AS `cooking_time_minutes`, `r`.`calories` AS `calories`, `r`.`image_url` AS `image_url`, `i`.`name` AS `ingredient_name`, `ri`.`quantity` AS `quantity`, `i`.`unit` AS `unit` FROM ((`recipes` `r` join `recipe_ingredients` `ri` on(`r`.`id_recipes` = `ri`.`recipe_id`)) join `ingredients` `i` on(`ri`.`ingredient_id` = `i`.`id_ingredients`)) ORDER BY `r`.`title` ASC, `i`.`name` ASC ;

