  ADD PRIMARY KEY (`id_categories`),
  ADD UNIQUE KEY `name` (`name`);

--
-- Индексы таблицы `chefs`
--
ALTER TABLE `chefs`
  ADD PRIMARY KEY (`id_chefs`);

--
-- Индексы таблицы `collections`
--
ALTER TABLE `collections`
  ADD PRIMARY KEY (`id_collections`),
  ADD KEY `user_id` (`user_id`);

--
-- Индексы таблицы `collection_recipes`
--
ALTER TABLE `collection_recipes`
  ADD PRIMARY KEY (`collection_id`,`recipe_id`),
  ADD KEY `idx_recipe_id` (`recipe_id`);

--
-- Индексы таблицы `complaints`
--
ALTER TABLE `complaints`
  ADD PRIMARY KEY (`id_complaints`),
  ADD KEY `user_id` (`user_id`);

--
-- Индексы таблицы `diets`
--
ALTER TABLE `diets`
  ADD PRIMARY KEY (`id_diets`),
  ADD UNIQUE KEY `name` (`name`);

--
-- Индексы таблицы `favorite_articles`
--
ALTER TABLE `favorite_articles`
  ADD PRIMARY KEY (`user_id`,`article_id`),
  ADD KEY `idx_article_id` (`article_id`),
  ADD KEY `idx_user_id` (`user_id`);

--
-- Индексы таблицы `favorite_chefs`
--
ALTER TABLE `favorite_chefs`
  ADD PRIMARY KEY (`user_id`,`chef_id`),
  ADD KEY `idx_chef_id` (`chef_id`),
  ADD KEY `idx_user_id` (`user_id`);

--
-- Индексы таблицы `favorite_collections`
--
ALTER TABLE `favorite_collections`
  ADD PRIMARY KEY (`user_id`,`collection_id`),
  ADD KEY `idx_collection_id` (`collection_id`),
  ADD KEY `idx_user_id` (`user_id`);

--
-- Индексы таблицы `favorite_recipes`
--
ALTER TABLE `favorite_recipes`
  ADD PRIMARY KEY (`user_id`,`recipe_id`),
  ADD KEY `idx_recipe_id` (`recipe_id`),
  ADD KEY `idx_user_id` (`user_id`);

--
-- Индексы таблицы `ingredients`
--
ALTER TABLE `ingredients`
  ADD PRIMARY KEY (`id_ingredients`),
  ADD UNIQUE KEY `name` (`name`);

--
-- Индексы таблицы `recipes`
--
