  ADD PRIMARY KEY (`id_recipes`),
  ADD KEY `chef_id` (`chef_id`);

--
-- Индексы таблицы `recipe_categories`
--
ALTER TABLE `recipe_categories`
  ADD PRIMARY KEY (`recipe_id`,`category_id`),
